const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_8","ls":"6.8","title":"Lernpfadübung · LS 6.8 · Über die Fortführung der Aktion entscheiden","version":"1.0","source":"Fachbereiche/BFSdual/LF06/LS_6_8_Folgeaktion_entscheiden.md"};
const COMP=[["Fachkompetenz","Ich vergleiche die Absatzzahlen und die Kundenrückmeldungen der beiden Läden. Ich prüfe, ob sie das Ziel erreicht haben. Ich begründe, was die Läden bei Sortiment, Platzierung und Werbung ändern oder beibehalten sollten."],["Personalkompetenz","Ich erkläre, was die Daten über meine Empfehlung aussagen und was offen bleibt."],["Sozialkompetenz","Ich beachte, was beiden Läden wichtig ist. Ich begründe eine gemeinsame Entscheidung."],["Methodenkompetenz","Ich vergleiche die Absatzmengen mit der Vergleichswoche. Ich prüfe, ob das Ergebnis zum Zielwert passt."],["Medienkompetenz","Ich stelle wichtige Zahlen und Rückmeldungen übersichtlich zusammen."]];
const BANK=[{"title":"Die Läden wollen eine Antwort","scene":"Zwei Geschäfte melden sich nach der Frühjahrsaktion bei Global Bike.","ask":"Welche Aussagen geben ihre Wünsche richtig wieder?","options":["Die Bike Arena möchte einen nächsten Termin festlegen.","Block möchte seine Fläche für andere Aktionen fest vergeben.","Block würde die Fläche wieder freihalten, möchte aber vorher etwas ändern.","Die Bike Arena möchte erst nach einer Standortbesichtigung eine Entscheidung treffen.","Nur Block bittet ausdrücklich um eine Antwort.","Beide Läden erwarten bis Freitag eine Antwort."],"answer":[0,2,5],"why":"Die Bike Arena möchte den nächsten Termin festlegen. Block hält die Fläche frei und möchte vor der Zusage etwas ändern. Beide erwarten bis Freitag eine Antwort.","hint":"Ordne zuerst jede Nachricht dem passenden Laden zu und suche den gemeinsamen Termin.","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["Handlungssituation"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Christians Ziel","scene":"Christian prüft den Aktionsbericht, bevor Jan die nächste Aktion empfiehlt.","ask":"Was genau wollte Global Bike erreichen?","options":["Zusammen sollten beide Läden 20 Stück mehr verkaufen.","Jeder Laden sollte mindestens 20 € mehr Umsatz pro Tag erreichen.","Jeder Laden sollte gegenüber seiner Vergleichswoche mindestens 20 % mehr Stück verkaufen.","Die Bike Arena sollte 20 % mehr Stück als Block verkaufen.","Mindestens 20 % aller Verkäufe sollten auf lokale Zusatzartikel entfallen.","Das Ziel war erreicht, sobald einer der beiden Läden 20 % mehr Stück verkaufte."],"answer":[2],"why":"Beide Standorte sollten jeweils mindestens 20 % mehr Stück aus dem Aktionssortiment verkaufen. Bezugswert ist die eigene Vergleichswoche.","hint":"Achte auf den Vergleichszeitraum, die Grenze und die Einheit.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M1"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was „Absatzmenge“ bedeutet","scene":"Die Bike Arena hat in der Aktionswoche 22 Minipumpen P50 verkauft.","ask":"Was bedeutet die Zahl 22 in der Tabelle?","options":["22 Kundinnen und Kunden fragten nach einer Minipumpe.","Die Minipumpen brachten 22 € Umsatz.","22 Minipumpen lagen am ersten Tag auf der Gondel.","22 Minipumpen wurden zusätzlich zur Vergleichswoche verkauft.","22 Minipumpen wurden in der Aktionswoche verkauft.","Global Bike hatte in beiden Läden zusammen 22 Minipumpen im Aktionsbestand."],"answer":[4],"why":"Absatzmengen sind verkaufte Stück. Die Zahl 22 erfasst die verkauften Minipumpen P50 in der Aktionswoche der Bike Arena.","hint":"Lies die Überschrift von M2 und unterscheide die Einheit Stück vom Umsatz in Euro.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M2","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Vergleichswoche richtig lesen","scene":"Beide Läden waren in beiden Wochen je fünf Tage geöffnet. Alle Aktionsartikel waren lieferbar.","ask":"Welche Regeln gelten beim Vergleich?","options":["Die Bike Arena ist die Vergleichswoche für Block.","Verglichen werden für jeden Laden seine eigenen Stückzahlen.","Leere Felder bedeuten, dass der Artikel in dieser Woche ausverkauft war.","Die beiden verglichenen Wochen umfassen in jedem Laden jeweils fünf Öffnungstage.","Allein das gleich lange Zeitfenster beweist die Wirkung einer Werbemaßnahme.","Ein leeres Feld kennzeichnet einen Artikel außerhalb des jeweiligen Aktionssortiments."],"answer":[1,3,5],"why":"Jeder Laden wird mit sich selbst verglichen. Gleiche Öffnungstage machen die Zeiträume besser vergleichbar. Leere Felder bedeuten, dass der Artikel im betreffenden Laden nicht zur Aktion gehört.","hint":"Prüfe, welche Woche zu welchem Laden gehört und was die Tabelle zu leeren Feldern erklärt.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Prozentänderung berechnen","scene":"Übungsvariante: Ein Laden verkauft in einer Vergleichswoche 20 Stück. In der Aktionswoche sind es 22.","ask":"Welche Rechenschritte liefern die prozentuale Absatzveränderung?","options":["Aktionsmenge minus Vergleichsmenge ergibt den Unterschied in Stück.","Die Differenz wird durch die Aktionsmenge geteilt, weil sie neuer ist.","Die Aktionsmenge wird durch 100 geteilt und direkt als Prozentwert ausgegeben.","Die Vergleichsmenge minus die Aktionsmenge zeigt die Zunahme.","Die Differenz wird durch die Vergleichsmenge geteilt und mit 100 multipliziert.","Die beiden Wochenmengen werden addiert, bevor man den Prozentwert berechnet."],"answer":[0,4],"why":"Zieht zuerst 20 von 22 ab. Teilt die 2 zusätzlichen Stück durch den alten Wert 20 und multipliziert mit 100. Das Ergebnis ist +10 %.","hint":"Überlege, welche Stückzahl am Anfang den Bezugspunkt bildet.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M5","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Kernsortiment und Ergänzungen","scene":"Die Frühjahrsaktion verbindet ein gemeinsames Angebot mit Artikeln für den jeweiligen Laden.","ask":"Welche Aussagen passen zum Aktionsbericht?","options":["Der Flaschenhalter F60 ist in beiden Läden Teil des Kernsortiments.","Die Minipumpe P50 gehört in beiden Läden zum Kernsortiment.","Block ergänzt die Aktion um den Sattelüberzug R40.","Die Bike Arena ergänzt die Aktion um die Minipumpe P50.","Die Bike Arena ergänzt die Aktion um F60 und B80.","Das Kernsortiment umfasst alle normalen Waren eines Ladens."],"answer":[1,2,4],"why":"Die P50 ist Teil des gemeinsamen Kernsortiments. Block führt zusätzlich R40. Die Bike Arena führt zusätzlich F60 und B80.","hint":"Achte darauf, welche Produkte in beiden Spalten stehen und welche nur einmal auftauchen.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M1"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Maßnahmen für die beiden Läden","scene":"Der Bericht fasst zusammen, wie die Läden ihre Kundschaft auf die Aktion aufmerksam machten.","ask":"Welche Zuordnungen stimmen?","options":["Block stellte eine unbetreute Beratungsgondel direkt ans Eingangsschild.","Block lud mit einem Newsletter zur Beratung ein.","Die Bike Arena verschickte einen Newsletter zur Vorführung.","In beiden Läden fand die Vorführung am Beratungsplatz statt.","Das Eingangsschild war Blocks wichtigste Werbemaßnahme.","Die Bike Arena zeigte Zubehör auf zwei Aktionsgondeln mit Produktkarten."],"answer":[1,5],"why":"Bei Block lud der Newsletter zur Beratung ein. Die Bike Arena nutzte ein Eingangsschild und zwei Aktionsgondeln mit Produktkarten zur Selbstbedienung.","hint":"Beachte für jeden Laden je eine Werbemaßnahme und eine Platzierung.","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M1"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Vorschläge einordnen","scene":"Jan braucht für jeden Laden Vorschläge zu Sortiment, Platzierung und Werbung.","ask":"Welche Zuordnungen sind fachlich richtig?","options":["Sortiment: R40 im Angebot behalten oder ersetzen.","Platzierung: Den Versandtag des Newsletters ändern.","Platzierung: Den Sattelüberzug aus dem Kassenbereich an ein Zubehörregal legen.","Werbung: Den Newsletter wieder einsetzen.","Werbung: Die Liste der Aktionsartikel im Lager ändern.","Sortiment: Die Aktionsgondel an eine besser sichtbare Stelle schieben."],"answer":[0,2,3],"why":"Die Auswahl der Artikel ist Sortiment. Der Platz im Laden ist Platzierung. Der Newsletter ist ein Werbemittel.","hint":"Bestimme, ob die Aussage das Angebot, den Ort im Laden oder die Ansprache beschreibt.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M4","M5"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was eine Kundenstimme aussagt","scene":"Eine Person bei Block sagt, dass sie wegen der angekündigten Lichtvorführung gekommen sei.","ask":"Welche Folgerungen sind begründet?","options":["Alle Besucherinnen und Besucher kamen wegen der Lichtvorführung.","Die Person nennt die Einladung im Newsletter als Grund für ihren Besuch.","Der Satz zeigt, um wie viel Prozent der Absatz gestiegen ist.","Die Rückmeldung kann dafür sprechen, die Einladung zur Vorführung beizubehalten.","Die Rückmeldung beweist, dass der Absatz ohne Newsletter gefallen wäre.","Mit dieser Aussage ist die Zielerreichung bei Block belegt."],"answer":[1,3],"why":"Das ist eine konkrete Rückmeldung zu einem Besuch. Sie hilft bei der Entscheidung über den Newsletter, lässt die Wirkung bei anderen Personen aber offen.","hint":"Frage dich, wer die Aussage macht und für wen sie gilt.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M3"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Sebastian und Christian abgleichen","scene":"Sebastian will schnell zusagen. Christian möchte vorher in den Aktionsbericht schauen.","ask":"Welche Aussagen passen?","options":["Sebastian sieht das Risiko, dass die Läden ihre Flächen für etwas anderes nutzen.","Sebastian hat den Preis der Folgeaktion bereits zugesagt.","Christian möchte Änderungen allein aus den Kundenstimmen ableiten.","Christian prüft die Zielerreichung und danach mögliche Verbesserungen anhand der Rückmeldungen.","Christian vergleicht ausschließlich, welcher Laden mehr Stück verkauft.","Jan möchte erst nach der nächsten Aktionswoche entscheiden."],"answer":[0,3],"why":"Sebastian befürchtet, dass die Läden ihre Flächen anderweitig vergeben. Christian prüft Zielwerte und Kundenrückmeldungen.","hint":"Welche Folge befürchtet Sebastian? Welche Belege braucht Christian?","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["Handlungssituation"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zahlen lesbar darstellen","scene":"Ihr stellt die Ergebnisse in einer Tabelle für Jan und die Läden zusammen.","ask":"Welche Spalten helfen bei der Entscheidung?","options":["Vergleichswoche und Aktionswoche getrennt, mit der Einheit Stück","Ein Eurobetrag in der Spalte, die mit Absatzmenge überschrieben ist","Eine gemeinsame Summe beider Läden anstelle der Standortwerte","Ein Prozentwert ohne Erklärung des Zeitraums","Prozentuale Veränderung je Laden gegenüber der Vergleichswoche","Ziel erreicht: je Laden „Ja“ oder „Nein“"],"answer":[0,4,5],"why":"Vorher und nachher brauchen klar beschriftete Stückzahlen. Dazu gehören prozentuale Veränderung und ein sichtbares Urteil am Zielwert.","hint":"Eine Person sollte ohne Rückfrage erkennen können, wie das Ergebnis zustande kommt.","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M2","M5"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Empfehlung begrenzen","scene":"In der Bike Arena fehlte einer Person beim Vergleich der Rahmentaschen die Angabe zur Rahmengröße. Ihr möchtet die Angabe auf der Produktkarte ergänzen.","ask":"Was könnt ihr mit dieser Rückmeldung begründen? Was bleibt offen?","options":["Aus der Rückmeldung folgt, dass die Mehrheit der Kundschaft die Angabe vermisste.","Die Rückmeldung stützt eine konkrete Ergänzung auf der Produktkarte.","Die Rückmeldung zeigt, um wie viel Prozent der Verkauf nach der Änderung steigen wird.","Die Rückmeldung erklärt, warum die Pumpe häufiger verkauft wurde.","Ob die geänderte Karte den Absatz erhöht, bleibt offen.","Die Rückmeldung beweist, dass die Rahmentasche aus dem Aktionssortiment gestrichen werden muss."],"answer":[1,4],"why":"Der Wunsch nach einer Größenangabe begründet die Ergänzung auf der Produktkarte. Ob die Angabe zu mehr Verkäufen führt und wie vielen Menschen sie hilft, müsste erst geprüft werden.","hint":"Trenne den Grund für die Änderung von einer Vorhersage über ihre Wirkung.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M3","M5","M6"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Block: Summe der Vergleichswoche","scene":"In Block wurden vorher 12 Lichtsets, 10 Schlösser, 8 Rahmentaschen, 5 Minipumpen und 5 Sattelüberzüge verkauft.","ask":"Welche Angaben belegen den Eintrag „Stück vorher“?","options":["35 Stück aus dem Aktionssortiment","40 € Umsatz aus dem Aktionssortiment","46 Stück in der Vergleichswoche","40 Stück aus dem Aktionssortiment","5 Stück aus dem Aktionssortiment","Der Zusatzartikel R40 zählt mit fünf Stück zur Summe."],"answer":[3,5],"why":"Für Block zählen die vier gemeinsamen Artikel und R40. 12 + 10 + 8 + 5 + 5 ergibt 40 verkaufte Stück.","hint":"Addiere alle fünf Zahlen dieser einen Spalte.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Block: Veränderung und Ziel","scene":"Bei Block wurden 40 Stück in der Vergleichswoche und 46 in der Aktionswoche verkauft. Ziel waren mindestens 20 % Zuwachs.","ask":"Welche Aussagen treffen zu?","options":["Block verkaufte 6 % mehr Stück.","Block verkaufte 6 Stück mehr.","Block steigerte den Absatz um rund 13 %.","Block steigerte den Absatz um 15 %.","Block erreichte das Ziel, weil die Aktionswoche mehr Verkäufe brachte.","Blocks Zuwachs lag 5 Prozentpunkte unter dem Zielwert."],"answer":[1,3,5],"why":"Es sind 6 Stück mehr. Die 6 zusätzlichen Stück bezogen auf 40 Stück ergeben +15 %. Der Wert liegt unter 20 %.","hint":"Unterscheide die Stückdifferenz vom Prozentwert und nutze 40 Stück als Bezugswert.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Bike Arena: Veränderung und Ziel","scene":"Die Bike Arena verkaufte 60 Stück in der Vergleichswoche und 75 in der Aktionswoche. Ziel waren mindestens 20 % Zuwachs.","ask":"Welche Angaben stimmen?","options":["Die Stückzahl stieg um 15.","Die Stückzahl stieg um 15 %.","Die Stückzahl stieg um 25 %.","Die Stückzahl stieg um 25 Stück.","Die Bike Arena erfüllte ihr Ziel.","Die Bike Arena erreichte das Ziel genau bei 20 %."],"answer":[0,2,4],"why":"Die Differenz beträgt 15 Stück. 15 ÷ 60 × 100 ergibt +25 %. Das liegt über der Zielmarke.","hint":"Beziehe die zusätzlichen 15 Stück auf den Wert der Vergleichswoche.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die gemeinsame Summe einordnen","scene":"Übungsvariante: Jemand addiert die Mengen beider Läden: von 100 auf 121 Stück. Er sagt: „Damit haben beide Läden das Ziel erreicht.“","ask":"Wie bewertest du die Aussage?","options":["Ein gemeinsamer Zuwachs von 21 % bedeutet automatisch mindestens 20 % je Laden.","21 % ist für beide Läden zusammen rechnerisch richtig.","Wenn ein Laden 25 % erreicht, muss man den anderen Standort nicht mehr prüfen.","Da sich beide Läden verbessert haben, sind beide Ziele erfüllt.","Für die Bike Arena gelten die 21 % anstelle des eigenen Prozentwerts.","Das gemeinsame Ergebnis beantwortet die Frage zur Zielerreichung je Laden nicht."],"answer":[1,5],"why":"Die Gesamtsumme wächst um 21 %. Da das Ziel pro Standort gilt, prüft ihr beide einzeln: Block liegt bei +15 %, die Bike Arena bei +25 %.","hint":"Unterscheide, für welche Gruppe der Prozentwert berechnet wurde und für wen die Zielmarke gilt.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M1","M2","M5"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Prozentfehler bei der Minipumpe","scene":"Übungsvariante: Die Bike Arena verkaufte P50 zuerst 17-mal und dann 22-mal. Jemand rechnet den Zuwachs mit 5 ÷ 22.","ask":"Welche Korrektur und Aussage sind richtig?","options":["Die fünf zusätzlichen Pumpen sind gleichbedeutend mit +5 %.","Der neue Wert 22 ist die richtige Basis für eine Absatzveränderung.","Der Zuwachs wird als 5 ÷ 17 × 100 gerechnet.","Der Zuwachs beträgt gerundet 29,4 %.","Die Rechnung liefert die Absatzveränderung des gesamten Ladens.","Ein höherer Prozentwert verändert die Stückdifferenz von 5 auf 6."],"answer":[2,3],"why":"Der alte Wert war 17 Stück. 5 ÷ 17 × 100 ergibt gerundet 29,4 % Zuwachs bei der Minipumpe der Bike Arena.","hint":"Welcher Wert beschreibt die Ausgangslage, bevor sich etwas verändert?","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M2","M5"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Platzierung bei Block verbessern","scene":"Eine Person entdeckte R40 erst an der Kasse. Eine andere Person wartete im Durchgang, weil am Beratungsplatz ein zweites Rad stand.","ask":"Welche Änderungen reagieren auf diese Beobachtungen?","options":["Den Sattelüberzug allein wegen unveränderter Verkäufe sofort aus dem Sortiment nehmen.","Den Sattelüberzug früher am Zubehörregal sichtbar machen.","Die Anzeige für P50 in der Bike Arena ändern.","Die Vorführung komplett durch ein Aktionsschild am Eingang ersetzen.","Bei der Beratung das zweite Fahrrad außerhalb des Durchgangs abstellen.","Das Kassenregal umstellen, ohne den Standort von R40 zu ändern."],"answer":[1,4],"why":"Die Kundenstimmen geben zwei Hinweise zur Platzierung: R40 früher sichtbar machen und den Durchgang bei der Vorführung freihalten.","hint":"Suche eine Maßnahme pro beobachtetem Problem.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M1","M3","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Produktkarten in Leer verbessern","scene":"In der Bike Arena fragt die Kundschaft nach der Rahmengröße für die Tasche und nach den Ventilen, zu denen die Pumpen passen.","ask":"Welche Änderungen machen den Vergleich leichter?","options":["Für die Rahmentasche angeben, zu welchen Rahmengrößen sie passt.","Bei allen Artikeln dieselbe Größenangabe ergänzen.","Nur den Produktnamen „Rahmentasche“ auf der Karte vergrößern.","An der Minipumpe die passenden Ventilarten nennen.","Die Frage zu den Ventilen durch einen Hinweis auf den Preis beantworten.","Das Eingangsschild neu drucken und die Produktkarten unverändert lassen."],"answer":[0,3],"why":"Die Produktkarten sollen die jeweilige Kompatibilität erklären. So beantworten sie die konkreten Fragen zur Tasche und Pumpe.","hint":"Zu welcher Entscheidung brauchen die Kundinnen und Kunden eine konkrete Angabe?","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M1","M3","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Beide Läden einbeziehen","scene":"Block möchte die Beratung verbessern. Die Bike Arena will Zubehör leichter vergleichbar machen.","ask":"Welche Empfehlungen setzen die Wünsche konkret um?","options":["In beiden Läden das Beratungsgespräch durch Selbstbedienung ersetzen.","Für Block einen Beratungsplatz vorsehen, der den Durchgang bei zwei Rädern freihält.","Bei Block alle Produktkarten ersetzen, ohne den Beratungsplatz zu prüfen.","Die Gondeln der Bike Arena in einen betreuten Beratungsstand umwandeln.","Für beide Läden ausschließlich einen gemeinsamen Rabatt vorschlagen.","Die Aktionsgondeln der Bike Arena beibehalten und die Produktkarten für den Vergleich ergänzen."],"answer":[1,5],"why":"Block braucht Platz für Beratung, ohne den Durchgang zu blockieren. Die Bike Arena braucht klare Produktinformationen an ihrer Insel.","hint":"Ordne die Wünsche der Ladenleitungen den passenden nächsten Schritten zu.","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Absatz und Werbewirkung unterscheiden","scene":"Die Bike Arena verkauft 25 % mehr Stück. Eine Person berichtet, dass sie das Eingangsschild neugierig gemacht habe.","ask":"Welche Aussagen sind durch die Informationen gedeckt?","options":["Der Absatz des Aktionssortiments ist um 25 % gestiegen.","Das Eingangsschild verursachte genau 25 % mehr Absatz.","Eine Person berichtet, dass das Schild ihr Interesse geweckt hat.","Die Aussage beweist, dass die Gondeln keine Wirkung hatten.","Mindestens ein Viertel der Kundschaft kam wegen des Schilds.","Der Beitrag des Schilds zum gesamten Zuwachs lässt sich aus diesen Angaben nicht berechnen."],"answer":[0,2,5],"why":"Der Anstieg ist messbar. Die Kundenstimme beschreibt einen einzelnen Besuch. Beides stützt einen weiteren Einsatz des Schilds als Vorschlag. Der Anteil des Schilds am Wachstum bleibt offen.","hint":"Trenne das Ergebnis aus der Rechnung, die einzelne Stimme und eine Behauptung über Ursachen.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M2","M3","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Zusatzprodukt abwägen","scene":"Bei Block wurden vor und während der Aktion jeweils fünf Sattelüberzüge R40 verkauft. Eine Person entdeckte ihn erst an der Kasse.","ask":"Welche nächsten Schritte lassen sich mit diesen Angaben begründen?","options":["R40 hat den Absatz von Block um 5 Stück erhöht.","R40 beim nächsten Mal besser sichtbar platzieren und die Stückzahl erneut festhalten.","R40 sofort aus allen Läden entfernen, weil kein Kunde ihn gefunden hat.","Das unveränderte Ergebnis zeigt, dass die Platzierung keinen Einfluss haben kann.","Den R40 in der Fortführung mit einer klaren Prüffrage beibehalten: Wird er an der neuen Stelle früher entdeckt?","R40 muss künftig in die Bike Arena verlegt werden, weil er dort im Bericht bereits mehr verkauft wurde."],"answer":[1,4],"why":"Unveränderter Absatz und spätes Entdecken sprechen dafür, einen sichtbareren Platz zu testen. Danach lässt sich der Absatz für R40 gezielt prüfen.","hint":"Ein unveränderter Absatz nennt noch keine Ursache. Nutze die Kundenrückmeldung als Hinweis für einen Test.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M2","M3","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Ergebnisse kurz berichten","scene":"Übungsvariante: Jan hat wenig Zeit. Du möchtest genau sagen, welcher Laden sein Ziel erreicht hat und was sich ändern soll.","ask":"Welche Aussagen passen in eine verlässliche Kurzvorlage?","options":["„Block: 40 → 46 Stück, +15 %, Ziel verfehlt.“","„Bike Arena: 60 → 75 Stück, +15 %, Ziel erreicht.“","„Beide Läden zusammen: +21 %. Beide erreichen damit jeweils ihr Ziel.“","„Bike Arena: Ergänzt die Rahmengröße auf der Taschenkarte. Diese Angabe fehlte beim Vergleich.“","„Block: Wählt eine neue Werbemaßnahme, weil sich keine Person an den Newsletter erinnern konnte.“","„Bike Arena: Die ursprüngliche Werbemaßnahme muss weg, weil Block sein Ziel verfehlte.“"],"answer":[0,3],"why":"Die Kurzvorlage soll die richtigen Standortwerte nennen und eine konkret belegte Änderung vorschlagen.","hint":"Prüfe erst die Zuordnung der Zahlen und danach den Zusammenhang zwischen Änderung und Rückmeldung.","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M2","M3","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Idee an einem neuen Standort prüfen","scene":"Jan überlegt, ob die Aktion auch zu einem weiteren Fahrradladen in Aurich mit Werkstatt passen könnte.","ask":"Welche Informationen braucht ihr für eine Empfehlung an diesen Laden?","options":["Die durchschnittliche Zielerreichung der beiden bisherigen Standorte als einzige Entscheidungsgrundlage","Welche Zubehörartikel die Kundschaft des neuen Ladens häufig nachfragt","Wo Zubehör und ein Rad zum Ausprobieren Platz finden","Ob der dritte Laden voraussichtlich dieselben Stückzahlen verkauft, weil er in Aurich liegt","Ob das Team Zeit für eine Vorführung oder Beratung einplanen kann","Welche Farben das Eingangsschild der Bike Arena hatte, damit sie unverändert übernommen werden"],"answer":[1,2,4],"why":"Nachfrage, verfügbare Fläche und Möglichkeiten für Beratung helfen bei der Standortentscheidung. Ergebnisse von Block und der Bike Arena lassen sich nicht ohne Prüfung übertragen.","hint":"Überlege, welche Unterschiede bei Angebot, Platz und Beratung die Umsetzung ändern können.","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["Handlungssituation"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Den Bericht eröffnen","scene":"Beide Läden wollen bis Freitag wissen, ob und wie die Frühjahrsaktion weitergeht. Jan braucht eine Empfehlung je Standort.","ask":"Mit welchem Schwerpunkt beginnst du die Vorbereitung?","options":["Prüfe zuerst die Standortwerte und die Rechnung zur Zielerreichung.","Sammle zuerst die wichtigsten Wünsche der beiden Läden und Fragen der Kundschaft.","Kläre zuerst, wer bis Freitag entscheidet und wer Änderungen vor Ort umsetzen kann.","Stelle Stückzahlen und Kundenstimmen pro Standort nebeneinander und markiere, was sie jeweils belegen.","Bereite eine kurze Abstimmung mit den Läden vor, damit du ihre Wünsche für die Folgeaktion richtig einordnen kannst.","Plane einen kurzen Ablauf für Datenauswertung, Freigabe und Rückmeldung bis Freitag."],"consequences":["Deine Empfehlung beginnt mit dem Absatz und dem Zielwert.","Deine Empfehlung beginnt mit Erwartungen und Rückmeldungen.","Deine Empfehlung beginnt mit Zuständigkeiten und der Umsetzungsfrist.","Du legst zwei Arten von Belegen für die Standortentscheidung bereit.","Du bindest beide Standorte in die Vorbereitung der Entscheidung ein.","Deine Entscheidungsvorlage hat einen realistischen Zeit- und Arbeitsrahmen."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Wähle deinen Schwerpunkt für den gesamten Entscheidungsweg.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M1","M5"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Blocks Ergebnis einordnen","scene":"Block steigt von 40 auf 46 Stück und verfehlt mit +15 % das Ziel von +20 %. Die Ladenleitung möchte weitermachen, wenn sich etwas ändert.","ask":"Wie bereitest du Blocks Entscheidung vor?","options":["Stelle Zuwachs und Zielabstand gegenüber und suche zu jeder vorgeschlagenen Änderung einen Beleg.","Kläre mit Blocks Ladenleitung, welche praktische Änderung eine erneute Teilnahme erleichtert.","Kläre, welchen Umbau Block vor dem nächsten Termin leisten kann und wer am Samstag die Beratung übernimmt.","Ordne die gleich gebliebenen Verkäufe von R40 und den Hinweis zum späten Entdecken als Prüfansatz für die Platzierung ein.","Vergleiche den Wunsch der Ladenleitung mit der Rückmeldung zum Warten im Durchgang.","Sichere den Termin vorläufig und halte fest, dass Block erst nach Klärung der Änderung verbindlich zusagt."],"consequences":["Du zeigst sowohl den Aufwärtstrend als auch die Zielverfehlung.","Die Folgeaktion kann an einer konkreten Anforderung des Ladens ansetzen.","Du prüfst, welche Anpassung vor Ort tatsächlich machbar ist.","Du verknüpfst zwei Hinweise, ohne daraus bereits eine Ursache abzuleiten.","Ein konkreter Kundenhinweis ergänzt die Sicht des Betriebs.","Du bewahrst den Zeitrahmen und respektierst Blocks Bedingung."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Nutze Blocks Wunsch und die Zielabweichung passend zu deinem Arbeitsweg.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["Handlungssituation","M2","M3","M5"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Bike Arena auswerten","scene":"Die Bike Arena erreicht +25 %. Einige Stimmen loben die schnelle Suche oder das Schild. Zur Rahmentasche und zur Minipumpe fehlen Angaben für den Produktvergleich.","ask":"Wie gehst du mit dem guten Ergebnis und den Rückfragen um?","options":["Dokumentiere das erreichte Ziel und nenne getrennt den Beleg für bessere Produktkarten.","Lass den Laden priorisieren, welche Kundenfrage auf den Karten zuerst beantwortet werden soll.","Plane ein, wer Rahmengrößen und Ventilangaben bis zur nächsten Aktion prüft und einträgt.","Belege aus den Stückzahlen den Erfolg der Aktion und nutze die Kundenstimmen für je eine Ergänzung an Tasche und Pumpe.","Bitte das Team, seine häufigsten Fragen an der Gondel mit den beiden vorhandenen Kundenhinweisen abzugleichen.","Diskutiere eine kleine Änderung der Produktkarten, die der Laden vor dem gewünschten Termin umsetzen kann."],"consequences":["Du unterscheidest den Absatzbefund vom Grund für die konkrete Änderung.","Die Produktkarten greifen die Kundensicht und die Erfahrungen der Mitarbeitenden auf.","Die Verbesserung erhält eine prüfbare Aufgabe mit Zuständigkeit.","Du leitest Zielurteil und Produktangaben aus passenden Belegen ab.","Du beziehst zusätzliche Erfahrungen der Personen ein, die die Gondel betreuen.","Die gute Platzierung kann bleiben, während die Produktinformationen innerhalb der verfügbaren Zeit ergänzt werden."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Behalte das erreichte Ziel im Blick und prüfe die offenen Produktinformationen.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M2","M3","M5"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Werbung für beide Läden abstimmen","scene":"Block möchte den Newsletter behalten. Eine Person berichtet, dass das Eingangsschild der Bike Arena sie neugierig gemacht habe.","ask":"Wie formulierst du den Werbeteil der Empfehlung?","options":["Empfiehl beide vorhandenen Mittel mit je einem Beleg und markiere, was über ihre Werbewirkung offenbleibt.","Gib beiden Ladenleitungen ihre jeweiligen Kundenhinweise zurück und hole eine Rückmeldung zum geplanten Werbemittel ein.","Kläre für beide Mittel, wer die Texte aktualisiert und wann Newsletter und Schild vorliegen müssen.","Nenne den Newsletterhinweis zur Vorführung bei Block und den berichteten ersten Eindruck am Eingang in Leer als zwei getrennte Belege.","Bitte beide Läden, beim nächsten Termin einige Kundinnen und Kunden zu fragen, wie sie auf die Aktion aufmerksam wurden.","Übernimm die unterschiedlichen Werbemittel in den Ablaufplan und ordne pro Laden eine verantwortliche Person zu."],"consequences":["Du begründest die getrennten Empfehlungen, ohne eine sichere Ursache zu behaupten.","Du nutzt Kundenstimmen als Gesprächsgrundlage mit den Läden.","Du hältst die Umsetzung für beide Werbemittel im vereinbarten Zeitrahmen.","Die Empfehlung bleibt für jeden Laden einzeln nachvollziehbar.","Du planst eine Rückmeldung, die für die nächste Entscheidung mehr Sichtweisen liefert.","Du sicherst, dass beide Werbemittel rechtzeitig bereitstehen."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Wähle einen nächsten Schritt, der aus den unterschiedlichen Rückmeldungen folgt.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["M1","M3","M5"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Grenzen der Auswertung benennen","scene":"Übungsvariante: Im Vorbereitungsgespräch meint jemand: „Die Prozentzahlen reichen doch. Damit wissen wir, ob Newsletter oder Schild besser funktionieren.“","ask":"Wie hältst du deine Empfehlung fachlich sauber?","options":["Stelle klar: Die Zahlen zeigen Absatzveränderungen. Für einen Vergleich der Werbewirkung fehlt ein Nachweis.","Ergänze die Prozentzahlen durch einzelne Kundenstimmen und kennzeichne, von wem die Aussagen tatsächlich kommen.","Vereinbare für die Folgeaktion einen Zeitpunkt und eine Zuständigkeit, um die Wirkung der Werbung gezielter zu prüfen.","Erläutere, dass Angebot, Platzierung und Werbung im selben Zeitraum zusammenwirken können. Beziehe die Rechnung allein auf die Absatzmenge.","Besprich mit den Ladenleitungen, welche Kundenfragen sie beim nächsten Termin aufnehmen möchten.","Kennzeichne die Werbeempfehlung in der Kurzvorlage als vorläufig. Plane eine kurze Überprüfung während der Folgeaktion ein."],"consequences":["Du trennst, was sich berechnen lässt und was die Daten nicht klären.","Du nutzt die dokumentierten Sichtweisen in ihrem tatsächlichen Umfang.","Du machst aus der offenen Frage einen planbaren Prüfschritt.","Du begrenzt die Schlussfolgerung auf das, was der Vergleich zeigt.","Du beziehst die Betriebe in die Klärung der offenen Werbefrage ein.","Du schlägst eine umsetzbare Entscheidung vor und lässt Raum für neue Erkenntnisse."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Behalte deinen Schwerpunkt und erkläre die Grenze der vorhandenen Zahlen.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M1","M2","M3","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Entscheidung an Jan weitergeben","scene":"Übungsvariante: Jan bittet am Freitag um eine letzte Empfehlung. Beide Läden hätten Platz, wenn die abgestimmten Änderungen bis zum nächsten Termin vorbereitet werden.","ask":"Welche Schlussfassung passt zu dem begonnenen Arbeitsweg?","options":["Empfiehl Block eine überarbeitete Fortführung und der Bike Arena eine Fortführung mit besseren Karten. Nenne +15 % und +25 % als Standortbelege.","Empfiehl eine Fortführung mit der Aufnahme von Blocks Beratungswunsch und den Vergleichsfragen aus Leer. Vereinbare eine gemeinsame Rückmeldung nach der Aktion.","Empfiehl die Termine unter der Bedingung, dass Block den Beratungsplatz und Leer seine Produktkarten rechtzeitig vorbereitet. Halte die Zuständigkeiten fest.","Halte die Zielerreichung je Laden fest und verknüpfe die Empfehlungen zu Angebot, Fläche und Werbung mit konkreten Belegen aus der Auswertung.","Gib beiden Ladenleitungen ihre Wünsche und die passenden Vorschläge zur letzten Abstimmung zurück. Notiere noch offene Rückfragen für Jan.","Lege einen Ablauf mit Bestätigung bis Freitag, Änderungen vor dem Termin und Auswertung danach vor."],"consequences":["Jan kann die Empfehlungen mit den berechneten Ergebnissen und den Änderungen verbinden.","Die Empfehlung verbindet beide Perspektiven mit einem vereinbarten Rückmeldeschritt.","Die Entscheidung ist an klare Voraussetzungen für die Umsetzung gebunden.","Der Entscheidungsweg bleibt für Jan und beide Läden überprüfbar.","Die Empfehlung bleibt an die Bedürfnisse der Läden und ihrer Kundschaft rückgebunden.","Du führst die Entscheidung bis zur Durchführung und erneuten Prüfung weiter."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Schließe mit einer klaren Empfehlung und dem nächsten Schritt für jeden Laden ab.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M2","M3","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]}];
